def upload_files_between_devices(local_dir, local_file, remote_device_name, remote_dir, timeout=20,
                                 local_device_name='UnixLocal', remove_source_file=False, log_level='warning', hops=[],
                                 new_file_name=None):
    r"""
    SCP files from UnixLocal device (local_dir, local_file) to remote device (remote_dir)

    :param local_dir: directory of the local file
    :param local_file: Name of file or files separated comma for eg file1.txt,file2.txt. You could use also regex:
    r'/^((HWF|SCFC_\d+)\.xml|swconfig.txt)$/' - regex need to be put between //
    'HWF.xml,SCFC_*.xml,swconfig.txt'
    :param remote_device_name: name of the destination device
    :param remote_dir: directory on the destination device
    :param timeout: scp timeout is seconds
    :param local_device_name: name of the source device
    :param remove_source_file: True if source file should be removed after upload, False otherwise
    :param log_level: info, warning or error
    :param new_file_name: If you would like scp file with new name. Works only for single file
    :param hops: list of device hops between local_device_name and remote_device_name.

    :return: None
    """
    scp_obj = ScpDeviceToDevice(local_dir=local_dir, source_file=local_file, remote_device_name=remote_device_name,
                                remote_dir=remote_dir, timeout=timeout, local_device_name=local_device_name,
                                remove_source_file=remove_source_file, log_level=log_level, hops=hops,
                                new_file_name=new_file_name)
    scp_obj.upload()


def download_files_between_devices(local_dir, remote_file, remote_device_name, remote_dir, timeout=20,
                                   local_device_name='UnixLocal', remove_source_file=False, log_level='warning',
                                   hops=[],
                                   new_file_name=None):
    r"""
    SCP files from Remote device (remote_dir, remote_file) to UnixLocal device (local_dir)

    :param local_dir: directory of the local file
    :param remote_file: Name of file or files separated comma for eg file1.txt,file2.txt. You could use also regex:
    r'/^((HWF|SCFC_\d+)\.xml|swconfig.txt)$/' - regex need to be put between //
    'HWF.xml,SCFC_*.xml,swconfig.txt'
    :param remote_device_name: name of the destination device
    :param remote_dir: directory on the destination device
    :param timeout: scp timeout is seconds
    :param local_device_name: name of the source device
    :param remove_source_file: True if source file should be removed after upload, False otherwise
    :param log_level: info, warning or error
    :param new_file_name: If you would like scp file with new name. Works only for single file
    :param hops: list of device hops between local_device_name and remote_device_name.

    :return: None
    """
    scp_obj = ScpDeviceToDevice(local_dir=local_dir, source_file=remote_file, remote_device_name=remote_device_name,
                                remote_dir=remote_dir, timeout=timeout, local_device_name=local_device_name,
                                remove_source_file=remove_source_file, log_level=log_level, hops=hops,
                                new_file_name=new_file_name)
    scp_obj.download()


def upload_files(local_dir, local_file, device_name, remote_dir, to_state=None, timeout=20,
                 remove_source_file=False, log_level='warning', new_file_name=None):
    r"""
    SCP file from/to local device to/from remote device. SCP is always performing on local device name

    :param local_dir: directory of the local file
    :param local_file: Name of file or files separated comma for eg file1.txt,file2.txt. You could use also regex:
    r'/^((HWF|SCFC_\d+)\.xml|swconfig.txt)$/' - regex need to be put between //
    'HWF.xml,SCFC_*.xml,swconfig.txt'
    :param device_name: name of the destination device
    :param to_state: to which device state upload - If not defined initial state will be used.
    :param remote_dir: directory on the destination device
    :param timeout: SCP timeout is seconds
    :param log_level: info, warning, error
    :param new_file_name: If you would like scp file with new name. Works only for single file
    :param remove_source_file: If set to True, source file(s) are removed after succeed scp
    """
    scp_obj = ScpDevice(local_dir=local_dir, source_file=local_file, device_name=device_name,
                        destination_state=to_state, remote_dir=remote_dir, timeout=timeout,
                        remove_source_file=remove_source_file, log_level=log_level,
                        new_file_name=new_file_name)
    scp_obj.upload()


def download_files(local_dir, remote_file, device_name, remote_dir, from_state=None, timeout=20,
                   remove_source_file=False, log_level='warning', new_file_name=None):
    r"""
    SCP file from/to local device to/from remote device. SCP is always performing on local device name

    :param local_dir: directory of the local file
    :param remote_file: Name of file or files separated comma for eg file1.txt,file2.txt. You could use also regex:
    r'/^((HWF|SCFC_\d+)\.xml|swconfig.txt)$/' - regex need to be put between //
    'HWF.xml,SCFC_*.xml,swconfig.txt'
    :param device_name: name of the destination device
    :param from_state: from which device state download - If not defined initial state will be used.
    :param remote_dir: directory on the destination device
    :param timeout: SCP timeout is seconds
    :param log_level: info, warning, error
    :param new_file_name: If you would like scp file with new name. Works only for single file
    :param remove_source_file: If set to True, source file(s) are removed after succeed scp
    """
    scp_obj = ScpDevice(local_dir=local_dir, source_file=remote_file, device_name=device_name,
                        destination_state=from_state, remote_dir=remote_dir, timeout=timeout,
                        remove_source_file=remove_source_file, log_level=log_level,
                        new_file_name=new_file_name)
    scp_obj.download()


class GenericScp(object):

    def __init__(self, local_dir, source_file, remote_dir, device_name, timeout=20, log_level='warning',
                 remove_source_file=False, hops=[], temp_dir='/tmp/', new_file_name=None):
        r"""
        SCP file from/to local device to/from remote device. SCP is always performing on local device name

        :param local_dir: directory of the local file
        :param source_file: Name of file or files separated comma for eg file1.txt,file2.txt. You could use also regex:
        r'/^((HWF|SCFC_\d+)\.xml|swconfig.txt)$/' - regex need to be put between //
        'HWF.xml,SCFC_*.xml,swconfig.txt'
        :param remote_dir: directory on the destination device
        :param device_name: name of the destination device
        :param timeout: SCP timeout is seconds
        :param log_level: info, warning, error
        :param new_file_name: If you would like scp file with new name. Works only for single file
        :param remove_source_file: If set to True, source file(s) are removed after succeed scp
        :param hops: list of device hops between local_device_name and remote_device_name. Direction is from
                     local_device_name to remote_device_name
        """

        self.local_dir = local_dir
        self.source_file = source_file
        self.remote_dir = remote_dir
        self.timeout = timeout
        self.log_level = log_level
        self.remove_source_file = remove_source_file
        self._default_options = '-o UserKnownHostsFile=/dev/null -o StrictHostKeyChecking=no -r'
        self.temp_dir = os.path.join(temp_dir, "{}_{}/".format(device_name, int(time.time())))
        self.new_file_name = new_file_name
        self.hops = hops
        self.hops_number = len(self.hops)
        self.last_hops_index = self.hops_number - 1

    def _single_upload(self, device, source_path, options, remote_host, remote_login, remote_password,
                       remote_dir, new_file_name=None):

        dest_location = os.path.join(remote_dir, new_file_name) if new_file_name else remote_dir
        remote_host = "[{}]".format(remote_host) if GenericScp._is_ipv6_address(remote_host) else remote_host
        scp_upload_files = device.get_cmd(cmd_name="scp",
                                          cmd_params={"source": "{} {}".format(options, source_path),
                                                      "dest": "{}@{}:{}".format(remote_login,
                                                                                remote_host,
                                                                                dest_location),
                                                      "password": remote_password})
        try:
            scp_upload_files(timeout=self.timeout)
        except CommandFailure as exception:
            self._log(msg=exception, level=self.log_level)

    def _single_download(self, device, source_path, options, local_dir, remote_password, new_file_name=None):

        dest_local = os.path.join(local_dir, new_file_name) if new_file_name else local_dir
        scp_download_files = device.get_cmd(cmd_name="scp",
                                            cmd_params={"source": "{} {}".format(options, source_path),
                                                        "dest": dest_local,
                                                        "password": remote_password})
        try:
            scp_download_files(timeout=self.timeout)
        except CommandFailure as exception:
            if "sftp-server: not found" in str(exception) and "-O" not in options:
                options += " -O"
                GenericScp._single_download(self, device=device, source_path=source_path, options=options,
                                            local_dir=local_dir, remote_password=remote_password,
                                            new_file_name=new_file_name)
                return
            self._log(msg=exception, level=self.log_level)

    def _get_upload_source_files(self, device):
        return self._get_source_files(device=device,
                                      source_dir=self.local_dir,
                                      source_file=self.source_file)

    @staticmethod
    def _build_upload_source_path(source_dir, file_names):

        file_paths = [os.path.join(source_dir, file_name) for file_name in file_names]
        source_path = " ".join(file_paths)

        return source_path

    def _get_download_source_files(self, device):
        return self._get_source_files(device=device,
                                      source_dir=self.remote_dir,
                                      source_file=self.source_file)

    def _get_source_files(self, device, source_dir, source_file):
        if source_file.startswith("/") and source_file.endswith("/"):
            file_names = self._get_files_from_pattern(connection=device,
                                                      pattern=source_file,
                                                      directory=source_dir)
        else:
            file_names = source_file.split(",")

        return file_names

    @staticmethod
    def _build_download_source_path(login, host, source_dir, file_names):
        source_files = ",".join(file_names)

        host = "[{}]".format(host) if GenericScp._is_ipv6_address(host) else host
        source_path = "{}@{}:{}".format(login, host, os.path.join(source_dir, source_files))
        if len(file_names) > 1:
            source_path = "{}@{}:{}/".format(login, host, source_dir)\
                          + r"{" + source_files + r"}"

        return source_path

    @staticmethod
    def _build_source_path_for_removing(source_dir, file_names):
        source_files = ",".join(file_names)
        if len(file_names) > 1:
            source_path_for_removing = source_dir + r"/{" + source_files + r"}"
        else:
            source_path_for_removing = source_dir + r"/" + source_files
        return source_path_for_removing

    def _make_directory(self, device, destination_dir):
        MolerTest.info(msg='Create directory on {}'.format(device.name))

        make_destination_directory = device.get_cmd(cmd_name="mkdir",
                                                    cmd_params={"path": destination_dir,
                                                                "options": "-p"})
        try:
            make_destination_directory()
        except CommandFailure as exception:
            self._log(msg=exception, level=self.log_level)

    def _remove_source_file(self, device, file_name):
        rm_cmd = device.get_cmd(cmd_name="rm", cmd_params={"file": file_name, "options": "-rf"})
        try:
            rm_cmd()
        except CommandFailure as exception:
            self._log(msg=exception, level=self.log_level)

    def _get_files_from_pattern(self, connection, pattern, directory):

        filtered = []

        try:
            ls_cmd = connection.get_cmd(cmd_name="ls", cmd_params={"options": "-1 {}".format(directory)})
            result = ls_cmd()
            files = result['files'].keys()
            filtered = GenericScp._filter_by_regex(source_list=files, pattern=pattern)
        except CommandFailure as exception:
            self._log(msg=exception, level="error")

        return filtered

    @staticmethod
    def _filter_by_regex(source_list, pattern):
        if pattern.startswith("/") and pattern.endswith("/"):
            pattern = pattern[1:-1]

        regex = re.compile(pattern)
        selected_items = list(filter(regex.search, source_list))

        return selected_items

    def _get_options(self, connection_params):
        if connection_params.get('options', None):
            options = "{} -r".format(connection_params['options'])
        else:
            options = self._default_options

        return options

    # 4268:2387:a881:40:43ff:fe80:126
    # 2a00:8a00:4000:4a7f::102d
    _re_ipv6 = re.compile(r'([\da-fA-F]+:)+')

    @staticmethod
    def _is_ipv6_address(ip_address):
        return GenericScp._re_ipv6.search(ip_address)

    @staticmethod
    def _log(msg, level='info'):
        """
        Wrapper for MolerTest logger.

        :param msg: String message
        :param level: info, warning, error
        :return: nothing
        """
        logger = getattr(MolerTest, level)

        if level == 'error':
            logger(msg=msg, raise_exception=True)
        else:
            logger(msg=msg)

    """Example of usage
    from scp import Scp
    scp = Scp(local_dir='/tmp/', source_file='test.txt', remote_device_name='WS0', remote_dir='/tmp/test')
    scp.upload()
    """


class ScpDeviceToDevice(GenericScp):

    def __init__(self, local_dir, source_file, remote_device_name, remote_dir, local_device_name='UnixLocal',
                 timeout=20, log_level='warning', remove_source_file=False, hops=[], temp_dir='/tmp/',
                 new_file_name=None):
        r"""
        SCP file from/to local device to/from remote device. SCP is always performing on local device name

        :param local_dir: directory of the local file
        :param source_file: Name of file or files separated comma for eg file1.txt,file2.txt. You could use also regex:
        r'/^((HWF|SCFC_\d+)\.xml|swconfig.txt)$/' - regex need to be put between //
        'HWF.xml,SCFC_*.xml,swconfig.txt'
        :param remote_device_name: name of the destination device
        :param remote_dir: directory on the destination device
        :param local_device_name: name of the source device
        :param timeout: SCP timeout is seconds
        :param log_level: info, warning, error
        :param new_file_name: If you would like scp file with new name. Works only for single file
        :param remove_source_file: If set to True, source file(s) are removed after succeed scp
        :param hops: list of device hops between local_device_name and remote_device_name. Direction is from
                     local_device_name to remote_device_name
        """

        self.remote_device_name = remote_device_name
        self.local_device_name = local_device_name
        hops = self._build_hops_table(hops)

        super(ScpDeviceToDevice, self).__init__(local_dir=local_dir, source_file=source_file,
                                                device_name=remote_device_name, remote_dir=remote_dir, timeout=timeout,
                                                log_level=log_level, remove_source_file=remove_source_file,
                                                temp_dir=temp_dir, new_file_name=new_file_name,
                                                hops=hops)

        self._connect_to_devices()
        self._set_credentials_of_remote_device()

    def _build_hops_table(self, hops):
        hops_table = hops[:]
        hops_table.insert(0, self.local_device_name)
        return hops_table

    def upload(self):
        files_names = self._get_upload_source_files(device=self.local_device)
        new_file_name = None

        for index, local_device_name in enumerate(self.hops):
            local_device = DeviceFactory.get_device(name=local_device_name)
            if index == 0:
                source_dir = self.local_dir
                remove_source_file = self.remove_source_file
            else:
                source_dir = self.temp_dir
                remove_source_file = True

            if index == self.last_hops_index:
                destination_dir = self.remote_dir
                remote_device = self.remote_device
                new_file_name = self.new_file_name
            else:
                destination_dir = self.temp_dir
                remote_device = DeviceFactory.get_device(name=self.hops[index + 1])

            self._make_directory(device=remote_device, destination_dir=destination_dir)
            remote_connection_params = self.get_connection_params(remote_device)
            source_path = self._build_upload_source_path(source_dir=source_dir, file_names=files_names)

            if source_dir == self.temp_dir:
                source_for_removing = self.temp_dir
            else:
                source_for_removing = source_path

            if len(files_names) > 1:
                new_file_name = None

            self._single_upload(device=local_device,
                                source_path=source_path,
                                options=self._get_options(remote_connection_params),
                                remote_host=remote_connection_params['host'],
                                remote_login=remote_connection_params['login'],
                                remote_password=remote_connection_params['password'],
                                remote_dir=destination_dir,
                                new_file_name=new_file_name)

            if remove_source_file:
                self._remove_source_file(device=local_device, file_name=source_for_removing)

    def download(self):
        files_names = self._get_download_source_files(device=self.remote_device)
        new_file_name = None

        reversed_hops = self.hops[::-1]
        for index, local_device_name in enumerate(reversed_hops):
            local_device = DeviceFactory.get_device(name=local_device_name)
            if index == 0:
                source_dir = self.remote_dir
                remote_device = self.remote_device
                remove_source_file = self.remove_source_file
            else:
                source_dir = self.temp_dir
                remote_device = DeviceFactory.get_device(name=reversed_hops[index - 1])
                remove_source_file = True

            if index == self.last_hops_index:
                local_dir = self.local_dir
                new_file_name = self.new_file_name
            else:
                local_dir = self.temp_dir

            self._make_directory(device=local_device, destination_dir=local_dir)
            remote_connection_params = self.get_connection_params(remote_device)
            source_path = self._build_download_source_path(login=remote_connection_params['login'],
                                                           host=remote_connection_params['host'],
                                                           source_dir=source_dir,
                                                           file_names=files_names)

            if source_dir == self.temp_dir:
                source_for_removing = self.temp_dir
            else:
                source_for_removing = self._build_source_path_for_removing(source_dir=source_dir,
                                                                           file_names=files_names)
            if len(files_names) > 1:
                new_file_name = None

            self._single_download(device=local_device,
                                  source_path=source_path,
                                  options=self._get_options(remote_connection_params),
                                  local_dir=local_dir,
                                  remote_password=remote_connection_params['password'],
                                  new_file_name=new_file_name)

            if remove_source_file:
                self._remove_source_file(device=remote_device, file_name=source_for_removing)

    @staticmethod
    def get_connection_params(device):
        """
        Get connection params for device.

        :param device: device connection
        :return: configuration
        """
        configuration = {}
        if isinstance(device, UnixRemote):
            configuration = ScpDeviceToDevice._get_unix_remote_configuration_params(device)
        elif isinstance(device, (Hub, FzmConsole)):
            configuration = device.get_configurations(source_state='PROXY_PC', dest_state='LINUX')
        elif isinstance(device, AirScale):
            if 'CPTY' in device.name:
                configuration = device.get_configurations(source_state='FCT', dest_state='FSP')
            else:
                configuration = device.get_configurations(source_state='PROXY_PC', dest_state='FCT')
        elif isinstance(device, RTG):
            configuration = device.get_configurations(source_state='UNIX_LOCAL', dest_state='WS')
        elif isinstance(device, RadioUnit):
            configuration = device.get_configurations(source_state='FHNET', dest_state='RU')
        elif isinstance(device, CloudBts):
            configuration = device.get_configurations(source_state='PROXY_PC', dest_state='OAM')
        else:
            MolerTest.error(msg="Unsupported device class", raise_exception=True)

        return configuration['command_params']

    @staticmethod
    def _get_unix_remote_configuration_params(device):
        try:
            configuration = device.get_configurations(source_state='UNIX_LOCAL', dest_state='UNIX_REMOTE')
        except KeyError:
            configuration = device.get_configurations(source_state='PROXY_PC', dest_state='UNIX_REMOTE')

        return configuration

    def _connect_to_devices(self):
        self.local_device = DeviceFactory.get_device(name=self.local_device_name)
        self.remote_device = DeviceFactory.get_device(name=self.remote_device_name)
        self.remote_device.goto_state(state=self.remote_device.initial_state)

    def _set_credentials_of_remote_device(self):

        connection_params = self.get_connection_params(self.remote_device)

        self.remote_host = connection_params['host']
        self.remote_login = connection_params['login']
        self.remote_password = connection_params['password']


class ScpDevice(GenericScp):

    def __init__(self, local_dir, source_file, device_name, remote_dir, destination_state=None, timeout=20,
                 log_level='warning', remove_source_file=False, temp_dir='~/', new_file_name=None):
        r"""
        SCP file from/to local device to/from remote device. SCP is always performing on local device name

        :param local_dir: directory of the local file
        :param source_file: Name of file or files separated comma for eg file1.txt,file2.txt. You could use also regex:
        r'/^((HWF|SCFC_\d+)\.xml|swconfig.txt)$/' - regex need to be put between //
        'HWF.xml,SCFC_*.xml,swconfig.txt'
        :param device_name: name of the destination device
        :param destination_state: from/to which state upload/download.
        :param remote_dir: directory on the destination device
        :param timeout: SCP timeout is seconds
        :param log_level: info, warning, error
        :param new_file_name: If you would like scp file with new name. Works only for single file
        :param remove_source_file: If set to True, source file(s) are removed after succeed scp
        """

        self.device_name = device_name
        self.device = DeviceFactory.get_device(name=self.device_name)
        self.destination_state = destination_state if destination_state else self.device.initial_state
        self.state_before = self.device.current_state
        hops = self._build_hops_table()

        super(ScpDevice, self).__init__(local_dir=local_dir, source_file=source_file, remote_dir=remote_dir,
                                        device_name=device_name,
                                        timeout=timeout, log_level=log_level, remove_source_file=remove_source_file,
                                        temp_dir=temp_dir, new_file_name=new_file_name, hops=hops)

    def _build_hops_table(self):
        hops_table = self._get_list_of_states(state_hops=self.device._state_hops,
                                              source_state='UNIX_LOCAL',
                                              destination_state=self.destination_state)

        scp_hops = self._get_scp_hops_and_credentials(hops_table=hops_table,
                                                      connection_hops=self.device._configurations['CONNECTION_HOPS'])
        return scp_hops

    @staticmethod
    def _get_list_of_states(state_hops, source_state, destination_state):
        is_dest_state = False
        next_state = source_state
        state_path = [next_state]
        while not is_dest_state:
            if destination_state in state_hops[next_state].keys():
                next_state = state_hops[next_state][destination_state]
            else:
                next_state = destination_state
                is_dest_state = True

            state_path.append(next_state)

        return state_path

    @staticmethod
    def _get_scp_hops_and_credentials(hops_table, connection_hops):
        scp_hops = []
        for index, current_state in enumerate(hops_table, start=0):
            if len(hops_table) == index + 1:
                break

            next_state = hops_table[index + 1]
            configuration = connection_hops[current_state][next_state]
            if configuration['execute_command'] == 'ssh':
                scp_hops.append({'state': current_state, 'params': configuration['command_params']})

        return scp_hops

    def upload(self):
        files_names = self._get_upload_source_files(state=self.hops[0]['state'])
        new_file_name = None
        MolerTest.info("[SCP] Upload file from UNIX_LOCAL state to {}".format(self.destination_state))
        for index, hop in enumerate(self.hops):
            if index == 0:
                source_dir = self.local_dir
                remove_source_file = self.remove_source_file
            else:
                source_dir = self.temp_dir
                remove_source_file = True

            if index == self.last_hops_index:
                destination_dir = self.remote_dir
                next_state = self.destination_state
                new_file_name = self.new_file_name
            else:
                destination_dir = self.temp_dir
                next_state = self.hops[index + 1]['state']

            MolerTest.info("[SCP][Step {}] Upload from {} to {}".format(index + 1, hop['state'], next_state))

            self._make_directory(state=next_state, destination_dir=destination_dir)

            remote_connection_params = hop['params']
            source_path = self._build_upload_source_path(source_dir=source_dir, file_names=files_names)

            if source_dir == self.temp_dir:
                source_for_removing = self.temp_dir
            else:
                source_for_removing = source_path

            if len(files_names) > 1:
                new_file_name = None

            self._single_upload(state=hop['state'],
                                source_path=source_path,
                                options=self._get_options(remote_connection_params),
                                remote_host=remote_connection_params['host'],
                                remote_login=remote_connection_params['login'],
                                remote_password=remote_connection_params['password'],
                                remote_dir=destination_dir,
                                new_file_name=new_file_name)

            if remove_source_file:
                self._remove_source_file(state=hop['state'], file_name=source_for_removing)

        self.device.goto_state(state=self.state_before)

    def download(self):
        files_names = self._get_download_source_files(state=self.destination_state)
        new_file_name = None

        reversed_hops = self.hops[::-1]
        MolerTest.info("[SCP] Download file from {} state to UNIX_LOCAL".format(self.destination_state))
        for index, hop in enumerate(reversed_hops):
            if index == 0:
                source_dir = self.remote_dir
                previous_state = self.destination_state
                remove_source_file = self.remove_source_file
            else:
                source_dir = self.temp_dir
                previous_state = reversed_hops[index - 1]['state']
                remove_source_file = True

            if index == self.last_hops_index:
                local_dir = self.local_dir
                new_file_name = self.new_file_name
            else:
                local_dir = self.temp_dir

            MolerTest.info("[SCP][Step {}] Download from {} to {}".format(index + 1, previous_state, hop['state']))

            self._make_directory(state=hop['state'], destination_dir=local_dir)

            remote_connection_params = hop['params']
            source_path = self._build_download_source_path(login=remote_connection_params['login'],
                                                           host=remote_connection_params['host'],
                                                           source_dir=source_dir,
                                                           file_names=files_names)

            if source_dir == self.temp_dir:
                source_for_removing = self.temp_dir
            else:
                source_for_removing = self._build_source_path_for_removing(source_dir=source_dir,
                                                                           file_names=files_names)
            if len(files_names) > 1:
                new_file_name = None

            self._single_download(state=hop['state'],
                                  source_path=source_path,
                                  options=self._get_options(remote_connection_params),
                                  local_dir=local_dir,
                                  remote_password=remote_connection_params['password'],
                                  new_file_name=new_file_name)

            if remove_source_file:
                self._remove_source_file(state=previous_state, file_name=source_for_removing)

        self.device.goto_state(state=self.state_before)

    def _remove_source_file(self, state, file_name):
        self.device.goto_state(state=state)
        super(ScpDevice, self)._remove_source_file(device=self.device, file_name=file_name)

    def _single_download(self, state, source_path, options, local_dir, remote_password, new_file_name):
        self.device.goto_state(state=state)
        super(ScpDevice, self)._single_download(device=self.device,
                                                source_path=source_path,
                                                options=options,
                                                local_dir=local_dir,
                                                remote_password=remote_password,
                                                new_file_name=new_file_name)

    def _single_upload(self, state, source_path, options, remote_host, remote_login, remote_password,
                       remote_dir, new_file_name):
        self.device.goto_state(state=state)
        super(ScpDevice, self)._single_upload(device=self.device,
                                              source_path=source_path,
                                              options=options,
                                              remote_host=remote_host,
                                              remote_login=remote_login,
                                              remote_password=remote_password,
                                              remote_dir=remote_dir,
                                              new_file_name=new_file_name)

    def _make_directory(self, state, destination_dir):
        self.device.goto_state(state=state)
        time.sleep(0.5)
        super(ScpDevice, self)._make_directory(device=self.device, destination_dir=destination_dir)
        time.sleep(0.5)

    def _get_download_source_files(self, state):
        self.device.goto_state(state=state)
        return super(ScpDevice, self)._get_download_source_files(device=self.device)

    def _get_upload_source_files(self, state):
        self.device.goto_state(state=state)
        return super(ScpDevice, self)._get_upload_source_files(device=self.device)
